function podeVer(v){if(v==="inicio")return true;{const g=podeVerG(v);if(g!==undefined)return g;}if(ehAdm())return true;switch(v){case "ruas":case "painel":return temPerm("aud_rua");case "retorno":return temPerm("aud_ret");case "cnt":return temPerm("aud_ret")||temPerm("aud_aer")||temPerm("aud_rua");case "cargas":return temPerm("aud_car");case "aero":return temPerm("aud_aer");case "pp":return temPerm("aud_pp");case "sac":return temPerm("aud_sac");case "adega":return temPerm("aud_adg");case "procura":return temPerm("aud_pro");case "com":return temPerm("aud_com");case "cesta":return temPerm("aud_ces");case "rot":return temPerm("aud_rot")||rotPriv();case "lib":return temPerm("aud_lib");case "dev":return temPerm("aud_dev");case "spk":return temPerm("aud_spk");case "sol":return temPerm("aud_sol");case "chep":return temPerm("aud_chp");case "vla":return temPerm("aud_vld");case "registros":return temPerm("aud_reg");case "noticias":return !!LOGIN;case "entret":return false;case "cha":return temPerm("aud_cha")||temPerm("aud_com");case "vales":return temPerm("aud_vale");case "prev":return temPerm("aud_pp")||temPerm("aud_vale");
  case "fechamento":return ["aud_fch","aud_rua","aud_ret","aud_car","aud_aer","aud_pp","aud_vale","aud_sac","aud_pro","aud_adg","aud_spk","aud_sol","aud_chp","aud_vld"].some(temPerm);case "val":return temPerm("aud_vld");default:return false;}}
function primeiraTela(){return ["ruas","retorno","cnt","spk","sol","vla","cargas","aero","pp","sac","adega","procura","vales","cha","com","cesta","lib","dev","rot","chep","fechamento"].find(podeVer)||"fechamento";}
function aplicarPerms(){setTimeout(gestAplicar,0);try{paintXnc();}catch(e){}let n=0;document.querySelectorAll("nav button[data-v]").forEach(b=>{const ok=podeVer(b.dataset.v);b.hidden=!ok;if(ok)n++;});
  document.querySelector("nav").style.setProperty("--nav-n",n);document.querySelector("nav").dataset.n=n;
  const fa=$("f-aba");if(fa){const pv=v=>podeVer(v==="validade"?"vla":v);[...fa.options].forEach(o=>o.hidden=!pv(o.value));if(!pv(fa.value)){const o=[...fa.options].find(x=>pv(x.value));if(o)fa.value=o.value;}}}
async function sha256(s){try{const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("");}catch(e){return "";}}
function lgMsg(m){$("lg-msg").textContent=m||"";}
function entrar(){setTimeout(()=>carregarApoio(),500);store.set("audcd_login",LOGIN);auditor=LOGIN.mat;store.set("audcd_auditor",auditor);$("login").hidden=true;aplicarPerms();paintWho();go("inicio");renderRecords();store.set("audcd_ultmat",LOGIN.mat);toast("Olá, "+String(nomeAud()).split(" ")[0]+".");setTimeout(()=>sheetSync(),300);setTimeout(()=>novMostrar(),900);setTimeout(()=>{if(!DEMO&&SHEET_URL&&navigator.onLine)carregarFech(false);},5000);}
async function fazerLogin(){
  const mat=$("lg-mat").value.replace(/\D/g,""),sen=$("lg-sen").value.trim();lgMsg("");
  if(!mat||!sen){lgMsg("Informe matrícula e senha.");return;}
  const bt=$("lg-go");bt.disabled=true;bt.textContent="Entrando…";
  const h=await sha256(mat+":"+sen+":auditoria-sta");
  try{
    if(navigator.onLine&&SHEET_URL){
      let j=null;
      try{const r=await fetch(SHEET_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({acao:"login",matricula:mat,senha:sen}),redirect:"follow",cache:"no-store"});j=await r.json();}catch(e){j=null;}
      if(j&&j.ok&&!j.token){lgMsg("O Apps Script publicado está desatualizado (não devolveu o acesso). Publique a versão nova: Implantar → Gerenciar implantações → lápis → Nova versão.");return;}
      if(j&&j.ok){LOGIN={mat:String(j.matricula),nome:j.nome||(cIdx.has(mat)?C.nome[cIdx.get(mat)]:""),perms:j.permissoes||[],token:j.token,hash:h,ts:Date.now()};
        const cr=store.get("audcd_creds",{});cr[mat]=LOGIN;store.set("audcd_creds",cr);$("lg-sen").value="";entrar();return;}
      if(j&&!j.ok){lgMsg(j.erro||"Matrícula ou senha inválidas.");return;}
    }
    const c=store.get("audcd_creds",{})[mat];
    if(c&&h&&c.hash===h){LOGIN=c;$("lg-sen").value="";entrar();toast("Entrou sem internet, com o último acesso validado neste aparelho.");return;}
    lgMsg(navigator.onLine?"Não foi possível falar com a planilha agora. Tente de novo.":(c?"Senha diferente da última usada neste aparelho.":"Sem internet: este aparelho ainda não tem acesso salvo para essa matrícula."));
  }finally{bt.disabled=false;bt.textContent="Entrar";}
}
