// impressão dos documentos originais (como os auditores imprimem)
function sessaoDe(r,L){if(r.Sessao)return r.Sessao;const f=L[0];
  if(r._aba==="cargas")return {id:r.ID_Sessao||("OS"+r.Numero_OS),os:r.Numero_OS,box:r.Box,conf:f.Matricula_Conferente,confNome:f.Nome_Conferente,aud:f.Matricula_Auditor,audNome:f.Nome_Auditor};
  const rua=unz(r.Rua)||String(fmtAddr(r.Endereco)).split("-")[0];const nc=L.find(x=>pbool(x.Possui_NC)&&x.Matricula_Colaborador_NC);const rm=nc?nc.Matricula_Colaborador_NC:(repsDaRua(rua)[0]||"");
  return {id:r.ID_Sessao||("R"+rua+"-"+String(r.DataHora||"").slice(0,10)),rua,rep:rm,repNome:nc?nc.Nome_Colaborador_NC:nomeC(rm),repFun:nc?(nc.Funcao_Colaborador_NC||""):(cIdx.has(rm)?C.fun[cIdx.get(rm)]:""),aud:f.Matricula_Auditor,audNome:f.Nome_Auditor};}
function docsOriginais(lista,base){const docs=[],feitos=new Set();const asc=lista.slice().sort((a,b)=>a.ts-b.ts);
  const doGrupo=(r,aba)=>{const L=base.filter(x=>(x._aba||"ruas")===aba&&x.ID_Sessao===r.ID_Sessao).sort((a,b)=>a.ts-b.ts);return L.length?L:[r];};
  asc.forEach(r=>{const aba=r._aba||"ruas";
    if(aba==="ruas"){if(pbool(r.Possui_NC))docs.push({html:docHTML(r),multi:false});}
    else if(aba==="sac"){docs.push({html:sacDocHTML(r),multi:false});}
    else if(aba==="adega"){docs.push({html:adgDocHTML(r),multi:false});}
    else if(aba==="pp"){docs.push({html:ppDocHTML(r),multi:false});}
    else if(aba==="validade"){if(pbool(r.Possui_NC))docs.push({html:vlaDocHTML(r),multi:false});}
    else if(aba==="retorno"){if(pbool(r.Possui_NC))docs.push({html:retNcDocHTML(r),multi:false});}
    else if(aba==="aero"){const k="a"+(r.Matricula_Operador||r.Operador)+"|"+String(r.DataHora||r.Data||"").slice(0,10);if(feitos.has(k))return;feitos.add(k);
      const L=base.filter(x=>x._aba==="aero"&&(x.Matricula_Operador||x.Operador)===(r.Matricula_Operador||r.Operador)&&String(x.DataHora||x.Data||"").slice(0,10)===String(r.DataHora||r.Data||"").slice(0,10));docs.push({html:aerDocHTML(L),multi:true});}
    else if(aba==="cargas"){const k="c"+(r.ID_Sessao||r.Numero_OS);if(feitos.has(k))return;feitos.add(k);const L=base.filter(x=>x._aba==="cargas"&&(r.ID_Sessao?x.ID_Sessao===r.ID_Sessao:x.Numero_OS===r.Numero_OS)).sort((a,b)=>a.ts-b.ts);if(L.some(x=>x.Causador==="Conferente"))docs.push({html:carDocHTML(sessaoDe(r,L),L),multi:true});}});
  return docs;}
async function makePdfLista(docs){if(!window.html2canvas)await loadScript(H2C);if(!(window.jspdf&&window.jspdf.jsPDF))await loadScript(JSPDF);
  const pdf=new window.jspdf.jsPDF({unit:"mm",format:"a4",orientation:docs[0]&&docs[0].land?"landscape":"portrait"});let primeira=true;
  for(const d of docs){const host=document.createElement("div");host.style.cssText=d.land?"position:fixed;left:-10000px;top:0;width:1123px;background:#fff;padding:0;box-sizing:border-box":d.wide?"position:fixed;left:-10000px;top:0;width:1123px;background:#fff;padding:0;box-sizing:border-box":"position:fixed;left:-10000px;top:0;width:794px;background:#fff;padding:34px 45px;box-sizing:border-box";host.innerHTML=d.html;host.querySelectorAll(".no-print").forEach(e=>e.remove());document.body.appendChild(host);
    if(d.land){await Promise.all([...host.querySelectorAll("img")].map(i=>i.complete?0:new Promise(ok=>{i.onload=i.onerror=ok;})));
      try{const cv=await window.html2canvas(host,{scale:1.7,backgroundColor:"#ffffff",logging:false,windowWidth:1200});if(!primeira)pdf.addPage("a4","landscape");
        let w=297,h=cv.height*w/cv.width;if(h>210){h=210;w=cv.width*h/cv.height;}pdf.addImage(cv.toDataURL("image/jpeg",.88),"JPEG",(297-w)/2,0,w,h);primeira=false;}finally{host.remove();}continue;}
    await Promise.all([...host.querySelectorAll("img")].map(i=>i.complete?0:new Promise(ok=>{i.onload=i.onerror=ok;})));
    try{const cv=await window.html2canvas(host,d.wide?{scale:1.7,backgroundColor:"#ffffff",logging:false,windowWidth:1200}:{scale:1.6,backgroundColor:"#ffffff",logging:false});const pageH=Math.floor(cv.width*297/210);
      if(!d.multi||cv.height<=pageH){if(!primeira)pdf.addPage("a4","portrait");let w=210,h=cv.height*w/cv.width;if(h>297){h=297;w=cv.width*h/cv.height;}pdf.addImage(cv.toDataURL("image/jpeg",.85),"JPEG",(210-w)/2,0,w,h);primeira=false;}
      else{const pc=document.createElement("canvas");pc.width=cv.width;const ctx=pc.getContext("2d");let y=0;
        while(y<cv.height){const h=Math.min(pageH,cv.height-y);pc.height=h;ctx.fillStyle="#fff";ctx.fillRect(0,0,pc.width,h);ctx.drawImage(cv,0,y,cv.width,h,0,0,cv.width,h);
          if(!primeira)pdf.addPage("a4","portrait");pdf.addImage(pc.toDataURL("image/jpeg",.85),"JPEG",0,0,210,h*210/cv.width);primeira=false;y+=pageH-60;}}}
    finally{host.remove();}}
  return pdf.output("blob");}
async function imprimirOriginais(){const L=filtered();if(!L.length){toast("Nada para imprimir com estes filtros.");return;}
  const base=regFonte()==="planilha"?sheetRecs():allRecs();
  if(regFonte()==="planilha"){const ids=new Set(L.map(r=>r.ID_Sessao).filter(Boolean));await carregarFotosPlanilha(base.filter(r=>L.includes(r)||(r.ID_Sessao&&ids.has(r.ID_Sessao))));}const docs=docsOriginais(L,base);
  if(!docs.length){toast("Nenhuma não conformidade com documento nestes filtros.");return;}
  if(docs.length>60&&!confirm(docs.length+" documentos. Pode demorar para gerar. Continuar?"))return;
  const per=regPeriodo();
  openDoc({html:docs.map(d=>'<div class="docsep">'+d.html+'</div>').join(""),pdfDocs:docs,multi:true,name:"NC_originais_"+todayISO()+".pdf",title:"Não conformidades – documentos",
    short:"Documentos de não conformidade – "+per.lab+" – "+docs.length+" documentos",text:"*NÃO CONFORMIDADES – DOCUMENTOS*\nPeríodo: "+per.lab+"\n"+docs.length+" documentos"});
  toast(docs.length+" documento"+(docs.length>1?"s":"")+" pronto"+(docs.length>1?"s":"")+" para imprimir.");}
$("x-orig").onclick=imprimirOriginais;


/* ---- Aéreo ---- */
function fxAero(){const rows=fxNoPeriodo(FECH.dados&&FECH.dados.aero).map(r=>Object.assign(r,{_q:pnum(r.Quantidade),_v:pnum(r["Vlr. Total"])})),tit="Auditoria Aéreo (operador) — Fechamento";
  const ops={};rows.forEach(r=>{const k=r.Matricula_Operador||r.Operador;const x=ops[k]=ops[k]||{n:r.Operador||k,i:0,q:0,v:0};x.i++;x.q+=r._q;x.v+=r._v;});
  const tipos={};rows.forEach(r=>{const k=String(r["Tipo de O.S"]||"—");tipos[k]=(tipos[k]||0)+1;});const ruas={};rows.forEach(r=>{const k=unz(r.Rua)||"—";ruas[k]=(ruas[k]||0)+1;});
  const aud={};rows.forEach(r=>{const k=r.Nome_Auditor||"—";aud[k]=(aud[k]||0)+1;});const itens={};rows.forEach(r=>{const k=r["Código"];const x=itens[k]=itens[k]||{d:r["Descrição"],i:0,q:0,v:0};x.i++;x.q+=r._q;x.v+=r._v;});
  const tot=rows.reduce((a,r)=>a+r._v,0),nOp=Object.keys(ops).length,maior=rows.slice().sort((a,b)=>b._v-a._v)[0],cores=["#2563EB","#7C3AED","#0EA5E9","#F97316","#16A34A","#CA8A04","#DC2626","#64748B"];
  const opTop=Object.values(ops).sort((a,b)=>b.i-a.i)[0];
  const porD={};rows.forEach(r=>{const k=fxDiaKey(r.ts);const x=porD[k]=porD[k]||{ts:r.ts,n:0};x.n++;});const linha=Object.keys(porD).sort().map(k=>({l:fxDia(porD[k].ts),v:porD[k].n,txt:String(porD[k].n)}));
  return fxHead(tit,rows.length)+
    fxKpis([{t:"Não conformidades",v:rows.length,c:"#DC2626",s:Object.keys(porD).length+" dia"+(Object.keys(porD).length===1?"":"s")+" com NC"},{t:"Operadores com NC",v:nOp,c:"#0F172A",s:nOp?(rows.length/nOp).toFixed(1).replace(".",",")+" NC por operador":""},
      {t:"O.S. auditadas",v:new Set(rows.map(r=>r["O.S"])).size},{t:"Valor médio por NC",v:BRL0(rows.length?tot/rows.length:0),c:"#B45309",s:maior?"maior: "+BRL0(maior._v)+" · "+curto(maior.Operador||""):""},
      {t:"Valor total",v:BRL0(tot),c:"#B45309",s:opTop?"mais NCs: "+curto(opTop.n)+" ("+opTop.i+")":""},...cntKpis()],true)+
    '<div class="fx-row" style="grid-template-columns:1fr 1fr">'+
      fxCard("NCs por operador",fxBars(Object.values(ops).sort((a,b)=>b.i-a.i||b.v-a.v).slice(0,8).map(x=>({l:curto(x.n),v:x.i,txt:x.i+" NC · "+BRL0(x.v),c:"#DC2626"}))).replace(/class="fx-bars"/,'class="fx-bars fx-bars-w"'))+
      fxCard("Ruas com mais ocorrências",fxBars(Object.entries(ruas).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,v])=>({l:"Rua "+k,v,txt:v+" NC",c:"#0EA5E9"}))))+'</div>'+
    '<div class="fx-row" style="grid-template-columns:1.7fr 1fr 1fr">'+
      fxCard("Itens com mais ocorrências",fxTable([{t:"Código"},{t:"Descrição"},{t:"Ocorr.",n:1},{t:"Un",n:1},{t:"Valor",n:1}],Object.entries(itens).sort((a,b)=>b[1].i-a[1].i||b[1].v-a[1].v).slice(0,6).map(([k,x])=>[esc(k),esc(String(x.d||"").slice(0,28)),x.i,x.q,BRL0(x.v)])))+
      fxCard("Tipo de O.S.",fxDonut(Object.entries(tipos).sort((a,b)=>b[1]-a[1]).map(([k,v],i)=>({l:"Tipo "+k,v,c:cores[i%cores.length]}))))+
      fxCard("Auditores — lançamentos",fxBars(Object.entries(aud).sort((a,b)=>b[1]-a[1]).map(([n,v])=>({l:curto(n),v,txt:String(v),c:"#3B82F6"}))).replace(/class="fx-bars"/,'class="fx-bars fx-bars-s"'))+'</div>'+
    fxFull("Lançamentos de não conformidade por dia (somente dias com auditoria)",fxLine(linha,"#DC2626",null,130))+fxFoot("Auditoria Aéreo");}

/* ---- Setores ---- */
function sobrasRows(){const src=(FECH.dados&&Array.isArray(FECH.dados.sobras)&&FECH.dados.sobras.length)?FECH.dados.sobras:SOBRAS;
  return dedupSobras(src).map(a=>({ts:pts(String(a[0]).replace(/^(\d{4})-(\d{2})-(\d{2})/,"$3/$2/$1")),os:a[1],cod:a[2],desc:a[3],q:pnum(a[4]),conf:a[6],sep:a[8],sepM:a[7],v:pnum(a[10]),tipo:a[12]||"Sobra"})).filter(o=>o.ts);}
/** Uma NC por separador + O.S. com sobra (regra da Expedição). */
function ncs8074(L){const m=new Map();L.filter(o=>o.tipo==="Sobra").sort((a,b)=>a.ts-b.ts).forEach(o=>{const k=(o.sepM||o.sep)+"|"+o.os;const x=m.get(k);if(x){x.itens++;x.q+=o.q;x.v+=o.v;}else m.set(k,{ts:o.ts,os:o.os,sep:o.sep,sepM:o.sepM,itens:1,q:o.q,v:o.v});});return [...m.values()];}
function fxPareto(S){const L=S.slice().sort((a,b)=>b.n-a.n),W=520,H=210,pl=12,pr=12,pt=18,pb=34,bw=(W-pl-pr)/L.length,mx=Math.max(1,...L.map(s=>s.n));
  return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" style="display:block"><line x1="'+pl+'" x2="'+(W-pr)+'" y1="'+(H-pb)+'" y2="'+(H-pb)+'" stroke="#E2E8F0"/>'+
    L.map((s,i)=>{const h=s.n/mx*(H-pt-pb),x=pl+bw*i+bw*.18;return '<rect x="'+x+'" y="'+(H-pb-h)+'" width="'+(bw*.64)+'" height="'+h+'" rx="3" fill="'+s.c+'"/><text x="'+(x+bw*.32)+'" y="'+(H-pb-h-5)+'" font-size="11" font-weight="700" text-anchor="middle" fill="#0F172A">'+s.n+'</text>'+
      '<text x="'+(x+bw*.32)+'" y="'+(H-pb+14)+'" font-size="9.5" text-anchor="middle" fill="#334155">'+esc(s.cur)+'</text>';}).join("")+'</svg>'+
    '<p class="fx-e" style="margin-top:2px">Não conformidades por setor, do maior para o menor. Reposição — ruas conta 1 NC por item; Separação vem da rotina 8074 (sobras sem duplicatas).</p>';}
/** Reposição — ruas: uma NC por rua por dia (várias linhas da mesma rua na mesma data contam 1). */
function ncRuaDia(rows){const m=new Map();rows.forEach(r=>{const rua=unz(r.Rua)||String(fmtAddr(r.Endereco)).split("-")[0];const k=rua+"|"+fxDiaKey(r.ts);
  let x=m.get(k);if(!x){x={ts:r.ts,Rua:rua,Valor_Divergencia:0,linhas:0,_p:{}};m.set(k,x);}x.ts=Math.min(x.ts,r.ts);x.linhas++;x.Valor_Divergencia+=pnum(r.Valor_Divergencia);
  if(r.Nome_Colaborador_NC)x._p[r.Nome_Colaborador_NC]=(x._p[r.Nome_Colaborador_NC]||0)+1;});
  return [...m.values()].map(x=>Object.assign(x,{Nome_Colaborador_NC:(Object.entries(x._p).sort((a,b)=>b[1]-a[1])[0]||[""])[0]}));}
function fxSetores(){const tit="Falhas de processos Logísticos";const [de,ate]=fxPeriodo();const len=Math.max(864e5,(isFinite(ate)?ate:Date.now())-de),pde=de-len;
  const ruasA=fxRows(FECH.dados&&FECH.dados.ruas).filter(r=>pbool(r.Possui_NC)),retA=fxRows(FECH.dados&&FECH.dados.retorno).filter(r=>pbool(r.Possui_NC)),carA=fxRows(FECH.dados&&FECH.dados.cargas),aerA=fxRows(FECH.dados&&FECH.dados.aero),valA=fxRows(FECH.dados&&FECH.dados.validade).filter(r=>pbool(r.Possui_NC)),s8=sobrasRows().filter(o=>o.tipo==="Sobra"),sobA=s8;
  const def=[{k:"rep",l:"Reposição — ruas",cur:"Repos. ruas",c:"#16A34A",rows:ruasA,val:r=>pnum(r.Valor_Divergencia),pes:r=>r.Nome_Colaborador_NC},
    {k:"ret",l:"Reposição — retorno",cur:"Repos. retorno",c:"#0E7490",rows:retA,val:r=>Math.abs(pnum(r.Valor_Divergencia)),pes:r=>r.Nome_Colaborador_NC},
    {k:"conf",l:"Cargas — conferência",cur:"Conferência",c:"#0EA5E9",rows:carA.filter(r=>r.Causador!=="Separador"),val:r=>pnum(r.Valor_Total),pes:r=>causadorDe(r).n},
    {k:"sep",l:"Separação — cargas (8074)",cur:"Separação",c:"#7C3AED",rows:sobA,val:r=>r.v,pes:r=>r.sep},
    {k:"aer",l:"Aéreo — operador",cur:"Aéreo",c:"#DC2626",rows:aerA,val:r=>pnum(r["Vlr. Total"]),pes:r=>r.Operador},
    {k:"val",l:"Reposição — validade",cur:"Repos. validade",c:"#B45309",rows:valA,val:r=>vlaVals(r).v,pes:r=>r.Nome_Colaborador_NC}];
  const S=def.map(d=>{const cur=d.rows.filter(r=>r.ts>=de&&r.ts<ate),ant=d.rows.filter(r=>r.ts>=pde&&r.ts<de);const v=cur.reduce((a,r)=>a+d.val(r),0);
    const p={};cur.forEach(r=>{const n=d.pes(r);if(n)p[n]=(p[n]||0)+1;});const topP=Object.entries(p).sort((a,b)=>b[1]-a[1])[0];
    return Object.assign({},d,{n:cur.length,ant:ant.length,v,med:cur.length?v/cur.length:0,pessoas:Object.keys(p).length,top:topP,cur:d.cur});});
  const tot=S.reduce((a,s)=>a+s.n,0),totV=S.reduce((a,s)=>a+s.v,0),totAnt=S.reduce((a,s)=>a+s.ant,0),ord=S.slice().sort((a,b)=>b.n-a.n),pior=ord[0];
  const varTxt=(n,a)=>a?((n-a)/a*100>0?"▲ ":"▼ ")+Math.abs(Math.round((n-a)/a*100))+"%":n?"novo":"—";const varCor=(n,a)=>n>a?"#DC2626":n<a?"#16A34A":"#64748B";
  const pessoas={};S.forEach(s=>s.rows.filter(r=>r.ts>=de&&r.ts<ate).forEach(r=>{const n=s.pes(r);if(!n)return;const x=pessoas[n+"|"+s.k]=pessoas[n+"|"+s.k]||{n,s,i:0,v:0};x.i++;x.v+=s.val(r);}));
  const sobPer=sobA.filter(r=>r.ts>=de&&r.ts<ate);
  const dias8=sobPer.reduce((o,r)=>{const k=fxDiaKey(r.ts);(o[k]=o[k]||{ts:r.ts,n:0}).n++;return o;},{}),ult8=Object.keys(dias8).sort().pop();
  const sub8=ult8?"último dia "+fxDia(dias8[ult8].ts)+": "+dias8[ult8].n+" · ":"";
  return fxHead(tit,tot)+
    fxKpis(S.map(s=>({t:s.l,v:s.n,c:s.c,s:(s.k==="sep"?sub8:"")+BRL0(s.v)+" · "+(tot?Math.round(s.n/tot*100):0)+"% · "+varTxt(s.n,s.ant),sc:varCor(s.n,s.ant)})).concat([{t:"Total de NCs",v:tot,c:"#0F172A",s:BRL0(totV)+" · "+varTxt(tot,totAnt)+" vs período anterior",sc:varCor(tot,totAnt)}]),true)+
    '<div class="fx-g"><div class="fx-col">'+fxCard("Não conformidades por setor",fxPareto(S))+'</div>'+
    '<div class="fx-col">'+fxCard("Setor com mais NCs",pior&&pior.n?'<p style="margin:2px 0 4px;font-size:24px;font-weight:700;color:'+pior.c+'">'+esc(pior.l)+'</p><p class="fx-e" style="color:#0F172A;font-size:12px">'+pior.n+' NCs · '+(tot?pc0(pior.n/tot):"")+' do total · '+BRL0(pior.v)+'<br>Maior ofensor: <b>'+esc(pior.top?curto(pior.top[0])+" ("+pior.top[1]+")":"—")+'</b> · '+varTxt(pior.n,pior.ant)+' vs período anterior</p>':'<p class="fx-e">Sem NCs no período.</p>')+
      fxCard("Participação no total",fxDonut(S.map(s=>({l:s.cur,v:s.n,c:s.c}))))+'</div></div>'+
    fxFull("Comparativo por setor",fxTable([{t:"Setor"},{t:"NCs",n:1},{t:"% do total",n:1},{t:"Valor",n:1},{t:"Valor médio/NC",n:1},{t:"Pessoas com NC",n:1},{t:"Maior ofensor"},{t:"Período anterior",n:1},{t:"Variação",n:1}],
      ord.map(s=>['<b style="color:'+s.c+'">'+esc(s.l)+'</b>','<b>'+s.n+'</b>',tot?pc0(s.n/tot):"—",BRL0(s.v),BRL0(s.med),s.pessoas,esc(s.top?curto(s.top[0])+" ("+s.top[1]+")":"—"),s.ant,'<b style="color:'+varCor(s.n,s.ant)+'">'+varTxt(s.n,s.ant)+'</b>'])))+
    '<div class="fx-g3" style="margin-top:10px">'+fxCard("Valor por setor",fxBars(S.slice().sort((a,b)=>b.v-a.v).map(s=>({l:s.cur,v:s.v,txt:BRL0(s.v),c:s.c}))))+
      fxCard("Colaboradores com mais NCs",fxBars(Object.values(pessoas).sort((a,b)=>b.i-a.i||b.v-a.v).slice(0,7).map(x=>({l:curto(x.n)+" · "+x.s.cur,v:x.i,txt:String(x.i),c:x.s.c}))))+
      fxCard("Sobras 8074 por separador (contagem)",(function(){const o={};sobPer.forEach(s=>{const k=s.sepM||s.sep||"—";const x=o[k]=o[k]||{n:s.sep||k,i:0,q:0,os:new Set()};x.i++;x.q+=s.q;x.os.add(s.os);});
        const L=Object.values(o).sort((a,b)=>b.i-a.i||b.q-a.q).slice(0,10);
        return fxBars(L.map(x=>({l:curto(x.n)+" · "+x.os.size+" O.S.",v:x.i,txt:x.i+" sobra"+(x.i===1?"":"s"),c:"#7C3AED"})))+'<p class="fx-e" style="margin-top:6px">Rotina 8074: cada sobra conta 1 NC no setor Separação. Somente quantidade superior, sem duplicatas (mesma O.S. e hora; mesmo item na O.S.). '+sobPer.length+' sobras de '+Object.keys(o).length+' separadores no período.</p>';})())+'</div>'+fxFoot("Setores auditados");}

// auditoria aéreo (operadores de empilhadeira)
const ENC_AERO={nome:"ANTONIO MAICON TEIXEIRA DE OLIVEIRA",mat:"10002407"};
const AER_COLS=["ID_Auditoria","Data","DataHora","Matricula_Operador","Operador","Código","Descrição","Rua","O.S","Tipo de O.S","Quantidade","Vl_Ult_Entrada","Vlr. Total","Observacao","Matricula_Auditor","Nome_Auditor","Status_NC"];
function searchOper(q){const L=searchColab(q);return L.sort((a,b)=>(/EMPILHADEIRA/.test(b.s)?1:0)-(/EMPILHADEIRA/.test(a.s)?1:0));}
const AE={prod:null,fotos:[]};
async function addFotoAE(e){const f=e.target.files[0];e.target.value="";if(!f||AE.fotos.length>=3)return;try{AE.fotos.push(await compress(f));setErr("a-foto-f","");paintAE();}catch(x){toast("Não foi possível ler a foto.");}}
$("a-foto").addEventListener("change",addFotoAE);$("a-foto-g").addEventListener("change",addFotoAE);
const aOp=picker($("a-op"),{ph:"Matrícula ou nome do operador",search:searchOper,describe:descColab,novo:true,onPick:k=>{if(k!=null)store.set("audcd_aero_op",C.mat[k]);paintAE();}});
const aProd=picker($("a-prod"),{ph:"Código ou descrição do item",search:searchProd,describe:descProd,onPick:k=>{AE.prod=k;paintAE();if(k!=null)setTimeout(()=>QW.a&&QW.a.focus(),50);}});
document.querySelectorAll("[data-aq]").forEach(b=>b.addEventListener("click",()=>{const i=$("a-qtd");i.value=Math.max(0,(parseInt(i.value,10)||0)+ +b.dataset.aq);paintAE();}));
$("a-qtd").addEventListener("input",paintAE);
function aeQ(){const v=String($("a-qtd").value).trim();return v===""?0:Math.max(0,parseInt(v,10)||0);}
function paintAE(){if(!$("a-valor"))return;if(window.QW&&QW.a)QW.a.refresh();const vl=AE.prod!=null?P.vl[AE.prod]:0,q=aeQ();
  $("a-valor").textContent=BRL.format(q*vl);$("a-calc").textContent=q+" un × "+BRL.format(vl)+" (Vl. ult. entrada 286)";$("a-data").textContent=fmtDT(new Date()).slice(0,10);
  const fb=$("a-fotos");fb.innerHTML=AE.fotos.map((s,i)=>'<div class="ph-it"><img src="'+s+'" alt="Foto '+(i+1)+'"><button type="button" data-i="'+i+'" aria-label="Remover foto">×</button></div>').join("");
  fb.querySelectorAll("button").forEach(b=>b.onclick=()=>{AE.fotos.splice(+b.dataset.i,1);paintAE();});$("a-cam").hidden=$("a-gal").hidden=AE.fotos.length>=3;listaAE();}
function aeHoje(){const t0=new Date();t0.setHours(0,0,0,0);return allRecs().filter(r=>r._aba==="aero"&&r.ts>=t0.getTime()&&r.Matricula_Auditor===auditor).sort((a,b)=>b.ts-a.ts);}
function listaAE(){const L=aeHoje();const g={};L.forEach(r=>{(g[r.Matricula_Operador]=g[r.Matricula_Operador]||[]).push(r);});
  $("a-list").innerHTML=L.length?'<div class="block"><h3>Lançamentos de hoje <small>'+L.length+'</small></h3>'+
    Object.entries(g).map(([m,rs])=>'<button type="button" class="save" data-anc="'+esc(m)+'" style="margin:4px 0 8px;min-height:46px;font-size:1.05rem">Imprimir NC – '+esc(curto(rs[0].Operador))+' ('+rs.length+')</button>').join("")+
    L.map(r=>'<div class="li"><div><div class="d"><b>'+esc(r["Código"])+'</b> – '+esc(r["Descrição"])+'</div><div class="tags"><span class="tag nc">'+esc(curto(r.Operador))+'</span><span class="tag">Rua '+esc(r.Rua)+'</span><span class="tag">O.S. '+esc(r["O.S"])+'</span><span class="tag">Tipo '+esc(r["Tipo de O.S"])+'</span></div></div>'+
      '<div><div class="v">'+esc(r.Quantidade)+' un<br>'+BRL.format(+r["Vlr. Total"]||0)+'</div><div class="act"><button type="button" class="btn sm" data-ax="'+esc(r.ID_Auditoria)+'">Excluir</button></div></div></div>').join("")+'</div>':"";
  $("a-list").querySelectorAll("[data-anc]").forEach(b=>b.onclick=()=>{const rs=L.filter(r=>r.Matricula_Operador===b.dataset.anc);openAerDoc(rs);});
  $("a-list").querySelectorAll("[data-ax]").forEach(b=>b.onclick=()=>delRec(b.dataset.ax).then(()=>paintAE()));}
function resetAE(){aProd.clear();AE.prod=null;AE.fotos=[];["a-rua","a-os","a-tipo","a-obs"].forEach(i=>$(i).value="");$("a-qtd").value="";if(window.QW&&QW.a)QW.a.reset();document.querySelectorAll("#v-aero .field.bad").forEach(f=>setErr(f.id,""));paintAE();}
$("a-save").addEventListener("click",async()=>{
  if(!auditor){toast("Faça login primeiro.");return;}
  const errs=[],chk=(c,f,m)=>{setErr(f,c?m:"");if(c)errs.push(f);};const q=aeQ(),rua=$("a-rua").value.replace(/\D/g,""),os=$("a-os").value.replace(/\D/g,""),tipo=$("a-tipo").value.trim();
  chk(aOp.value==null,"a-op-f","Informe o operador.");chk(AE.prod==null,"a-prod-f","Informe o item.");chk(!rua,"a-rua-f","Informe a rua.");chk(!os,"a-os-f","Informe a O.S.");
  chk(!tipo,"a-tipo-f","Informe o tipo de O.S.");chk(!(q>0),"a-qtd-f","Informe a quantidade encontrada.");chk(!AE.fotos.length,"a-foto-f","Tire ao menos uma foto da ocorrência.");
  if(errs.length){$(errs[0]).scrollIntoView({block:"center",behavior:"smooth"});toast("Revise os campos marcados.");return;}
  const now=new Date(),k=AE.prod,vl=P.vl[k],oi=aOp.value;
  const rec={_aba:"aero",ID_Auditoria:newId("AE"),Data:fmtDT(now).slice(0,10),DataHora:fmtDT(now),ts:now.getTime(),Matricula_Operador:C.mat[oi],Operador:C.nome[oi],
    "Código":P.cod[k],"Descrição":P.desc[k],Rua:String(+rua),"O.S":os,"Tipo de O.S":tipo,Quantidade:q,Vl_Ult_Entrada:vl,"Vlr. Total":Math.round(q*vl*100)/100,
    Observacao:$("a-obs").value.trim(),Matricula_Auditor:auditor,Nome_Auditor:nomeAud(),Possui_NC:true,Status_NC:"Aberta",fotos:AE.fotos.slice()};
  $("a-save").disabled=true;const ok=await saveRec(rec);$("a-save").disabled=false;resetAE();window.scrollTo(0,0);
  toast((ok||dbState==="off"?"Lançamento salvo":"Salvo neste aparelho, envio pendente")+" – "+BRL.format(rec["Vlr. Total"])+".");aProd.focus();});
function aerDocHTML(L){L=L.slice().sort((a,b)=>a.ts-b.ts);const f=L[0],tot=L.reduce((a,r)=>a+(+r["Vlr. Total"]||pnum(r["Vlr. Total"])||0),0),un=L.reduce((a,r)=>a+(+r.Quantidade||pnum(r.Quantidade)||0),0);
  const row=(k,v)=>'<tr><td class="k">'+k+'</td><td>'+(v===""||v==null?"–":esc(v))+'</td></tr>';const obs=L.filter(r=>r.Observacao).map(r=>r["Código"]+": "+r.Observacao);
  return '<div class="pd"><div class="pd-h"><img src="'+LOGO_BLUE+'" alt="Santa Therezinha"><div class="r"><h1>Não conformidade – Operação aéreo</h1><p>Operador de empilhadeira · '+esc(f.Data||String(f.DataHora||"").slice(0,10))+'</p></div></div>'+
   '<h2>Identificação</h2><table>'+row("Data",f.Data||String(f.DataHora||"").slice(0,10))+row("Operador",(f.Operador||"")+" – matrícula "+(f.Matricula_Operador||""))+row("Auditor",(f.Nome_Auditor||"")+" – matrícula "+(f.Matricula_Auditor||""))+'</table>'+
   '<div class="sum"><div><b>'+L.length+'</b><span>ocorrências</span></div><div><b>'+un+'</b><span>unidades</span></div><div><b>'+BRL.format(tot)+'</b><span>valor total</span></div><div><b>'+[...new Set(L.map(r=>r["O.S"]))].length+'</b><span>O.S.</span></div></div>'+
   '<h2>Ocorrências</h2><table class="lt"><thead><tr><th>Código</th><th>Descrição</th><th>Rua</th><th>O.S.</th><th>Tipo</th><th>Qtd.</th><th>Vl. un.</th><th>Vlr. total</th></tr></thead><tbody>'+
   L.map(r=>{const q=+r.Quantidade||pnum(r.Quantidade)||0,v=+r["Vlr. Total"]||pnum(r["Vlr. Total"])||0;return '<tr><td>'+esc(r["Código"])+'</td><td>'+esc(r["Descrição"])+'</td><td class="n">'+esc(r.Rua)+'</td><td class="n">'+esc(r["O.S"])+'</td><td class="n">'+esc(r["Tipo de O.S"])+'</td><td class="n">'+q+'</td><td class="n">'+BRL.format(+r.Vl_Ult_Entrada||(q?v/q:0))+'</td><td class="n">'+BRL.format(v)+'</td></tr>';}).join("")+
   '</tbody><tfoot><tr><td colspan="5">Total</td><td class="n">'+un+'</td><td></td><td class="n">'+BRL.format(tot)+'</td></tr></tfoot></table>'+
   '<p class="decl" style="margin-top:6px">Valor total = quantidade encontrada × Vl. ult. entrada da base 286.</p>'+
   (obs.length?'<h2>Observações</h2><div class="obs">'+esc(obs.join("\n"))+'</div>':'')+
   fotosHTML(L.flatMap(r=>(r.fotos||[]).map(s=>({s,c:r["Código"]+" · Rua "+r.Rua}))))+
   termoHTML([TERMO_TXT.aero],tot)+
   '<p class="decl">Declaro ciência das não conformidades registradas na auditoria da operação aéreo.</p>'+
   '<div class="sg"><div><b>Operador</b>'+esc(f.Operador||"")+'<small>Matrícula '+esc(f.Matricula_Operador||"")+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Auditor</b>'+esc(f.Nome_Auditor||"")+'<small>Matrícula '+esc(f.Matricula_Auditor||"")+'</small><small>Data: ___/___/______</small></div>'+
   '<div><b>Encarregado do setor</b>'+ENC_AERO.nome+'<small>Matrícula '+ENC_AERO.mat+'</small><small>Data: ___/___/______</small></div></div></div>';}
