const ceBRL=n=>{const v=+n||0,tr=Math.trunc(v*100+(v>=0?1e-6:-1e-6))/100;return tr.toLocaleString("pt-BR",{style:"currency",currency:"BRL",minimumFractionDigits:2,maximumFractionDigits:2});};
const ceNum=n=>(+n||0).toLocaleString("pt-BR",{maximumFractionDigits:2});
