const ceDataBR=v=>{v=String(v==null?"":v);if(/^\d{4}-\d{2}-\d{2}T/.test(v)){const d=new Date(v);if(!isNaN(d))return String(d.getDate()).padStart(2,"0")+"/"+String(d.getMonth()+1).padStart(2,"0")+"/"+d.getFullYear();}const m=v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);return m?m[1].padStart(2,"0")+"/"+m[2].padStart(2,"0")+"/"+m[3]:v;};
const ceRows=j=>(j&&j.registros||[]).map(r=>{const o={};(j.colunas||[]).forEach((c,i)=>o[c]=r[i]==null?"":String(r[i]));if("Data" in o)o.Data=ceDataBR(o.Data);if(o.Chave&&o.Matricula)o.Chave=o.Data+"|"+o.Matricula;return o;});
const CE_REP0={oper:["10002564"],conf:["10002517","10003033"],rep:["10003725"]};
