// ===== Cesta básica (painel embutido) =====
function cestaAbrir(){const f=$("cb-frame");if(f&&!f.getAttribute("src"))f.setAttribute("src","cesta.html");}
function cestaEnviar(file,tipo){const f=$("cb-frame");cestaAbrir();const go=()=>{try{const w=f.contentWindow;if(w&&w.cestaArquivo&&w.document.readyState==="complete"){w.cestaArquivo(file,tipo);toast(tipo==="foto"?"Lendo a foto no painel…":"Importando a planilha no painel…");return true;}}catch(e){toast("Não consegui enviar o arquivo ao painel.");return true;}return false;};
  if(!go()){let n=0;const t=setInterval(()=>{if(go()||++n>40)clearInterval(t);},250);}}
$("cb-xlsx").addEventListener("change",e=>{const f=e.target.files[0];e.target.value="";if(f)cestaEnviar(f,"xlsx");});
$("cb-foto").addEventListener("change",e=>{const f=e.target.files[0];e.target.value="";if(f)cestaEnviar(f,"foto");});
