    Tipo:DG.tipo,Codigo_Produto:P.cod[k],Descricao_Produto:P.desc[k],Quantidade:q,Vl_Unitario:vl,Valor:Math.round(q*vl*100)/100,Numero_Carga:$("d-car").value,Numero_Nota:$("d-nf").value,
