const cntKpis=()=>{const C=cntPeriodo(),sf=fxNoPeriodo(FECH.dados&&FECH.dados.contagem).filter(cntSemFoto).length;return [{t:"Lançamentos sem foto",v:sf,c:sf?"#DC2626":"#16A34A",s:sf?"podem ter desconto na comissão":"todos com foto"},{t:"Ruas auditadas",v:C.totRuasDia.toLocaleString("pt-BR"),c:"#0EA5E9",s:C.dias?"soma de todas as auditorias · "+C.ruasUni.size+" ruas diferentes · "+C.dias+" dia(s) · média "+C.medRuas.toFixed(1).replace(".",",")+"/dia":"sem contagem no período"},{t:"Endereços auditados",v:C.totEnd.toLocaleString("pt-BR"),c:"#0369A1",s:C.dias?"média "+Math.round(C.medEnd).toLocaleString("pt-BR")+" por dia":"pela base de cada rua"}];};
