  const porD={};rows.forEach(r=>{const x=porD[r._d]=porD[r._d]||{n:0};x.n++;});const linha=Object.keys(porD).sort().map(k=>({l:ceBr(k).slice(0,5),v:porD[k].n,txt:String(porD[k].n)}));
