const pDe=k=>Object.keys(PAINEIS).find(n=>{const c=PAINEIS[n];return c.keys?c.keys.includes(k):(k.startsWith(c.prefix)&&!(c.fora||[]).includes(k));});
const pVer=n=>+(localStorage.getItem("audcd_pv_"+n)||0);
function pInfo(n,txt){PS.info[n]=txt;const el=$("pinfo-"+n);if(el)el.textContent=txt;}
function pMesclar(loc,rem){let a,b;try{a=JSON.parse(loc);b=JSON.parse(rem);}catch(e){return loc;}
  const chave=x=>x&&typeof x==="object"?(x.id||x.ID||x.num||x.numero||x.seq||JSON.stringify(x)):JSON.stringify(x);
  if(Array.isArray(a)&&Array.isArray(b)){const m=new Map();b.forEach(x=>m.set(String(chave(x)),x));a.forEach(x=>m.set(String(chave(x)),x));return JSON.stringify([...m.values()]);}
  if(a&&b&&typeof a==="object"&&typeof b==="object"&&!Array.isArray(a)&&!Array.isArray(b))return JSON.stringify(Object.assign({},b,a));
  return loc;}
async function painelPuxar(n,recarregar){if(PS.puxando[n]||DEMO||!SHEET_URL||!navigator.onLine||!LOGIN)return false;PS.puxando[n]=true;
  try{const j=await ppPost({acao:"painel_ler",painel:n});if(!j.versao||!j.dados){const tem=pKeys(n).some(k=>localStorage.getItem(k));pInfo(n,tem?"Publicando os dados deste aparelho para todos…":"Ainda não há dados compartilhados: a próxima importação será publicada para todos.");if(tem)setTimeout(()=>painelEnviar(n),300);return false;}
    if(j.versao<=pVer(n)){pInfo(n,"Atualizado para todos · última publicação "+j.em+" por "+j.por);return false;}
    const c=PAINEIS[n];if(!c.keys)pKeys(n).forEach(k=>{if(!(k in j.dados))localStorage.removeItem(k);});
    Object.entries(j.dados).forEach(([k,v])=>{try{if(v==null)localStorage.removeItem(k);else localStorage.setItem(k,v);}catch(e){}});
    localStorage.setItem("audcd_pv_"+n,String(j.versao));pInfo(n,"Atualizado para todos · última publicação "+j.em+" por "+j.por);
    const f=$(c.frame);if(recarregar!==false&&f&&f.getAttribute("src"))f.setAttribute("src",c.src+"?v="+j.versao);
    return true;}catch(e){pInfo(n,"Não consegui buscar a versão compartilhada: "+e.message);return false;}finally{PS.puxando[n]=false;}}
async function painelEnviar(n){if(DEMO||!SHEET_URL||!LOGIN)return;const c=PAINEIS[n];pInfo(n,"Publicando para todos…");
  try{const dados={};pKeys(n).forEach(k=>dados[k]=localStorage.getItem(k));
    if(c.merge){try{const r=await ppPost({acao:"painel_ler",painel:n});if(r.dados)Object.entries(r.dados).forEach(([k,v])=>{if(v==null)return;dados[k]=dados[k]==null?v:pMesclar(dados[k],v);});}catch(e){}
      Object.entries(dados).forEach(([k,v])=>{try{if(localStorage.getItem(k)!==v)localStorage.setItem(k,v);}catch(e){}});}
    const tam=JSON.stringify(dados).length;if(tam>45e6)throw new Error("dados grandes demais para publicar");
    const j=await ppPost({acao:"painel_salvar",painel:n,dados});localStorage.setItem("audcd_pv_"+n,String(j.versao));pInfo(n,"Publicado para todos · "+j.em+" por "+j.por);toast("Painel atualizado para todos que têm acesso.");}
  catch(e){pInfo(n,"Não publicou: "+e.message+" (tenta de novo na próxima alteração)");}}
/* qualquer alteração feita dentro de um painel (importação, lançamento, cadastro) é publicada */
window.addEventListener("storage",e=>{if(!e.key)return;const n=pDe(e.key);if(!n||PS.puxando[n])return;clearTimeout(PS.timer[n]);PS.timer[n]=setTimeout(()=>painelEnviar(n),2500);});
/* atualiza sozinho enquanto o painel está aberto */
setInterval(()=>{if(document.hidden)return;Object.keys(PAINEIS).forEach(n=>{const v=$("v-"+n);if(v&&!v.hidden)painelPuxar(n);});},60000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden)Object.keys(PAINEIS).forEach(n=>{const v=$("v-"+n);if(v&&!v.hidden)painelPuxar(n);});});
/* ---- Devoluções ---- */
function devAbrir(){const f=$("dv-frame");if(f&&!f.getAttribute("src"))f.setAttribute("src","devolucoes.html");}
function devEnviar(file){const f=$("dv-frame");devAbrir();const go=()=>{try{const w=f.contentWindow;if(w&&w.painelArquivo&&w.document.readyState==="complete"){w.painelArquivo(file);toast("Importando a planilha de devoluções…");return true;}}catch(e){toast("Não consegui enviar o arquivo ao painel.");return true;}return false;};
  if(!go()){let k=0;const t=setInterval(()=>{if(go()||++k>40)clearInterval(t);},250);}}
$("dv-xlsx").addEventListener("change",e=>{const f=e.target.files[0];e.target.value="";if(f)devEnviar(f);});
/* ---- Chamada e comissão: sempre a versão mais recente da planilha ---- */
setInterval(async()=>{if(document.hidden||!CE.cfg||CE.busy)return;const v=["cha","com"].find(x=>{const s=$("v-"+x);return s&&!s.hidden;});if(!v)return;
  const ae=document.activeElement;if(ae&&(ae.tagName==="INPUT"||ae.tagName==="TEXTAREA"||ae.tagName==="SELECT")&&ae.closest("#v-"+v))return;
  try{const j=await ppPost({acao:"cha_ler"});CE.cha=ceRows(j);if(j.config&&j.config.equipe)CE.cfg=Object.assign(CE.cfg,{equipe:j.config.equipe,atividades:j.config.atividades||CE.cfg.atividades,valores:Object.assign({},CE.cfg.valores,j.config.valores||{}),repasses:j.config.repasses||CE.cfg.repasses});
    if(v==="com"&&ceCom()){const l=await ppPost({acao:"cl_ler"});CE.lanc=ceRows(l).filter(x=>x.ID).map(x=>Object.assign(x,{_d:ceIso(x.Data),_q:ceParse(x.Quantidade),_v:ceParse(x.Valor_Unitario),_t:ceParse(x.Total)}));}
    ceRender();}catch(e){}},45000);

