function msgDia(){const d=new Date(),i=Math.floor((d-new Date(d.getFullYear(),0,0))/864e5);return {fe:MSG_FE[i%MSG_FE.length],lg:MSG_LOG[(i*7+3)%MSG_LOG.length]};}
