    inv:{k:"inv",t:"Inventário",esc:"Individual",un:"itens",meta:(c.invMes/4)*fat,real:inv.n,sub:"Rotina 8066: itens atualizados no período · meta de "+(+c.invMes).toLocaleString("pt-BR")+" itens por mês ("+Math.round(c.invMes/4).toLocaleString("pt-BR")+" por semana) · responsável: "+gmRespNomes("inv"),perm:"aud_rot",campo:"inv",semDados:inv.ok?"":"Carregando a rotina 8066…"},
