function gmHojeEquipe(){const D=FECH.dados;if(!D){if(!FECH.busy)carregarFech(false);return [{t:"Auditorias hoje (equipe)",v:0,c:"#2563EB"},{t:"Não conformidades hoje",v:0,c:"#DC2626"},{t:"Auditores ativos hoje",v:0,c:"#0D9488"},{t:"Metas no ritmo (semana)",v:0,c:"#7C3AED"}];}
  const t0=new Date();t0.setHours(0,0,0,0);const T=t0.getTime(),abas=["ruas","retorno","cargas","procura","saldo","validade","contagem","aero"];let n=0,nc=0;const quem={};
  abas.forEach(a=>fxRows(D[a]).filter(r=>r.ts>=T).forEach(r=>{n++;if(ehNC(Object.assign({_aba:a},r)))nc++;const k=gmNk(r.Nome_Auditor||r.Matricula_Auditor);if(k){const q=quem[k]=quem[k]||{nome:r.Nome_Auditor||r.Matricula_Auditor,n:0,nc:0};q.n++;if(ehNC(Object.assign({_aba:a},r)))q.nc++;}}));
  GM.hoje=Object.values(quem).sort((a,b)=>b.n-a.n);let ok=0,tot=0;try{const R=gmCalc(gmPeriodo("semana",0));Object.values(R.M).forEach(m=>{if(m.ref!=null){tot++;if(m.ref>=1)ok++;}});}catch(e){}
  return [{t:"Auditorias hoje (equipe)",v:n,c:"#2563EB"},{t:"Não conformidades hoje",v:nc,c:"#DC2626"},{t:"Auditores ativos hoje",v:GM.hoje.length,c:"#0D9488"},{t:"% das metas no ritmo (semana: "+ok+" de "+tot+")",v:tot?Math.round(ok/tot*100):0,c:"#7C3AED"}];}
