/* os emojis "olham" para o mouse e pulam ao toque */
(function(){let raf=0,alvo=null,ev=null;const zera=g=>{g.style.setProperty("--lx",0);g.style.setProperty("--ly",0);};
  document.addEventListener("pointermove",e=>{ev=e;if(raf)return;raf=requestAnimationFrame(()=>{raf=0;const c=ev.target&&ev.target.closest?ev.target.closest(".gm-c"):null;
    if(alvo&&alvo!==c){alvo.querySelectorAll(".gm-look").forEach(zera);alvo.querySelectorAll(".gm-em.on").forEach(x=>x.classList.remove("on"));}alvo=c;if(!c)return;
    c.querySelectorAll(".gm-look").forEach(g=>{const r=g.getBoundingClientRect(),dx=(ev.clientX-(r.left+r.width/2))/140,dy=(ev.clientY-(r.top+r.height/2))/140;g.style.setProperty("--lx",Math.max(-1,Math.min(1,dx)).toFixed(3));g.style.setProperty("--ly",Math.max(-1,Math.min(1,dy)).toFixed(3));});
    c.querySelectorAll(".gm-em").forEach(x=>{const r=x.getBoundingClientRect(),d=Math.hypot(ev.clientX-(r.left+r.width/2),ev.clientY-(r.top+r.height/2));x.classList.toggle("on",d<26);});});},{passive:true});
  document.addEventListener("click",e=>{const t=e.target&&e.target.closest?e.target.closest(".gm-ec,.gm-em"):null;if(!t)return;const c=t.closest(".gm-c"),ec=c&&c.querySelector(".gm-ec");if(!ec)return;ec.classList.remove("pop");void ec.getBoundingClientRect();ec.classList.add("pop");setTimeout(()=>ec.classList.remove("pop"),850);});})();

// ===================== NC automática por meta, alerta de advertência e ociosidade =====================
/* NC automática só a partir da primeira semana completa com o app (16/11/2026) */
const NCA_INICIO="2026-11-16";
const NCA_TIPO_META="Meta não atingida — baixa produtividade",NCA_TIPO_ADV="Solicitação de advertência";
var NCST=(function(){try{return store.get("audcd_ncst",{})||{};}catch(e){return {};}})();
function ncaTodas(){return ncaLista().map(r=>NCST[r.ID_Auditoria]?Object.assign({},r,NCST[r.ID_Auditoria]):r);}
const ncaEhMeta=r=>String(r.Tipo||"").indexOf("Meta não atingida")===0;
const ncaKey=r=>String(r.Matricula_Colaborador||"").trim()||gmNk(r.Nome_Colaborador);
/* semana encerrada a avaliar: a partir de sábado vale a semana atual (seg a sex); antes disso, a anterior */
function ncaSemanaAlvo(){const d=new Date().getDay();return gmPeriodo("semana",(d===6||d===0)?0:-1);}
function ncaSeg(P){const d=new Date(P.ate);const w=d.getDay();d.setDate(d.getDate()+((8-w)%7));return d;}
/* quem não bateu: meta individual (validade) abaixo de 100%; metas da equipe não atingidas e contribuição abaixo da parte de cada um */
function ncaFalhas(R,x){const F=[];["spk","ret","aero","cc"].forEach(k=>{const m=R.M[k];if(!m||m.pct==null||m.pct>=1||!gmResp(x,k))return;const part=R.L.filter(y=>y[m.campo]>0&&gmResp(y,k)).length;if(!(x[m.campo]>0)||!part)return;const parte=m.meta/part;
    if(x[m.campo]<parte)F.push({k,m,real:x[m.campo],meta:parte,pct:x[m.campo]/parte,txt:m.t+": "+gmFmt(m,x[m.campo])+" de "+gmFmt(m,parte)+" "+(m.un==="R$"?"":m.un)+" (parte individual da meta da equipe; equipe fez "+Math.round(m.pct*100)+"%)"});});
  if(R.M.vld&&R.M.vld.conv){const v=R.M.vld.conv;if(gmResp(x,"vld")&&x.vldC&&v.fim&&v.fim<Date.now()&&v.real<v.END)F.push({k:"vld",m:R.M.vld,real:v.real,meta:v.END,pct:v.pct,txt:"Validade: "+v.real+" de "+v.END+" endereços da convocação ativa zerados até o fim do prazo"});}
  else if(gmResp(x,"vld")&&x.vld&&x.vld.dev>0&&x.vld.ok<x.vld.dev)F.push({k:"vld",m:R.M.vld,real:x.vld.ok,meta:x.vld.dev,pct:x.vld.ok/x.vld.dev,txt:"Validade: "+x.vld.ok+" de "+x.vld.dev+" itens zerados em até "+gmCfg().vldDias+" dias"});
  return F;}
async function ncaGerarAuto(){if(GM.autoBusy||!gPerm("ce_gest")||!FECH.fresh||DEMO)return;const P=ncaSemanaAlvo();if(new Date(P.de).toISOString().slice(0,10)<NCA_INICIO)return;
  GM.autoBusy=true;try{await Promise.all([gmCarregarCfg(),gmUsuarios(),gmValidade()]);
    const R=gmCalc(P);Object.values(R.M).forEach(m=>{m.rit=1;});const wk=new Date(P.de),wkS=wk.getFullYear()+String(wk.getMonth()+1).padStart(2,"0")+String(wk.getDate()).padStart(2,"0");
    const ex=new Set(ncaTodas().map(r=>String(r.ID_Auditoria)));ncaExcl().forEach(x=>ex.add(x));const seg=ncaSeg(P);let n=0;
    for(const x of R.L){const F=ncaFalhas(R,x);if(!F.length)continue;const id="NCA-A"+wkS+"-"+(x.mat||gmNk(x.nome).replace(/ /g,""));if(ex.has(id))continue;const now=new Date();
      await saveRec({_aba:"ncaud",ID_Auditoria:id,Data:fdISO(todayISO()),DataHora:fmtDT(now),ts:now.getTime(),Matricula_Auditor:NC_GESTOR.mat,Nome_Auditor:NC_GESTOR.nome,Matricula_Colaborador:x.mat,Nome_Colaborador:x.nome,Tipo:NCA_TIPO_META,
        Meta:F.map(f=>f.m.t).join(" · "),Periodo:P.lab,Meta_Valor:F.map(f=>f.m.k==="vld"?f.meta+" itens":gmFmt(f.m,f.meta)).join(" · "),Realizado:F.map(f=>f.m.k==="vld"?f.real+" itens":gmFmt(f.m,f.real)).join(" · "),Percentual:F.map(f=>Math.round(f.pct*100)+"%").join(" · "),
        Descricao:"Gerada automaticamente no fechamento da semana ("+P.lab+"). O colaborador não atingiu o resultado esperado até sexta-feira: "+F.map(f=>f.txt).join("; ")+". Orientação: "+F.map(f=>GM_DICA[f.k]).filter(Boolean).join(" "),
        Medida:"Orientação e plano de ação",Prazo:seg.toISOString().slice(0,10),Status:"Pendente de aplicação",Origem:"Automática",Chave:id});n++;}
    if(n)toast(n+" não conformidade(s) por meta gerada(s) automaticamente para aplicar na segunda-feira.");}catch(e){}
  GM.autoBusy=false;ncaAlertas();}
/* alertas: NCs pendentes de aplicação e colaboradores com 2 NCs por baixa produtividade sem advertência solicitada */
function ncaResumo(){const T=ncaTodas(),pend=T.filter(r=>r.Status==="Pendente de aplicação"),porC={};
  T.forEach(r=>{const k=ncaKey(r);if(!k)return;const c=porC[k]=porC[k]||{k,mat:r.Matricula_Colaborador,nome:r.Nome_Colaborador,meta:[],adv:[],outras:[]};if(r.Tipo===NCA_TIPO_ADV)c.adv.push(r);else if(ncaEhMeta(r)&&r.Status!=="Dispensada"&&r.Status!=="Pendente de aplicação")c.meta.push(r);else c.outras.push(r);});
  const adv=Object.values(porC).map(c=>{const ult=c.adv.reduce((m,r)=>Math.max(m,r.ts||0),0),novas=c.meta.filter(r=>(r.ts||0)>ult).sort((a,b)=>(a.ts||0)-(b.ts||0));return Object.assign(c,{novas});}).filter(c=>c.novas.length>=2);
  return {T,pend,porC,adv};}
/* situações (Aplicada/Dispensada) que não chegaram na planilha: tenta de novo */
async function ncaStatusPend(){if(DEMO||!SHEET_URL||!navigator.onLine||GM.stBusy)return;const L=Object.entries(NCST).filter(([,v])=>v&&v._pend);if(!L.length)return;GM.stBusy=true;let ok=0;
  for(const [id,v] of L){const h=HIST.get(id);if(h&&h._sheet!==SHEET_URL)continue;try{const j=await ppPost({acao:"ncaud_status",id,status:v.Status,aplicadaEm:v.Aplicada_Em,aplicadaPor:v.Aplicada_Por});if(j&&j.ok){delete v._pend;ok++;}}catch(e){}}
  try{store.set("audcd_ncst",NCST);}catch(e){}GM.stBusy=false;if(ok&&$("v-ncaud")&&!$("v-ncaud").hidden)paintNCA();}
/* NCs gravadas no aparelho que ainda não chegaram na planilha */
function ncaNaoEnviadas(){const H=[...HIST.values()].filter(r=>r._aba==="ncaud"&&r._sheet!==SHEET_URL),S=Object.values(NCST).filter(v=>v&&v._pend).length;
  if(DEMO||!SHEET_URL||(!H.length&&!S))return "";const err=(H.find(r=>r._sheetErr)||{})._sheetErr||lastSheetErr||"";
  return '<div class="hm-card nca-al nca-adv" style="text-align:left"><b>'+(H.length?H.length+' não conformidade(s) ainda não salva(s) na planilha Google':'')+(H.length&&S?' · ':'')+(S?S+' situação(ões) aguardando envio':'')+'</b>'+
    (err?'<small style="display:block;margin-top:4px">Motivo: '+esc(err)+(/desconhecido|Atualize o Apps Script/i.test(err)?' — cole o Apps Script novo e publique em Gerenciar implantações → lápis → Nova versão.':'')+'</small>':'')+
    '<small id="nca-ver" style="display:block;margin-top:4px;color:var(--muted)">Conferindo a versão do Apps Script…</small><button type="button" class="btn" id="nca-env" style="margin-top:8px">Enviar agora</button></div>';}
/* lê a versão do Apps Script de um link /exec */
async function sheetVer(u){try{const r=await fetch(u+(u.includes("?")?"&":"?")+"t="+Date.now(),{cache:"no-store"});const j=await r.json();return j&&j.ok?j:null;}catch(e){return null;}}
/* se este aparelho guardou um link antigo e o link padrão já roda versão mais nova, troca sozinho */
async function sheetMelhorLink(){if(DEMO||!SHEET_URL||SHEET_URL===SHEET_DEFAULT||!navigator.onLine)return false;const [a,b]=await Promise.all([sheetVer(SHEET_URL),sheetVer(SHEET_DEFAULT)]);
  if(b&&(+b.versao||0)>(a?(+a.versao||0):-1)){SHEET_URL=SHEET_DEFAULT;store.set("audcd_sheet_url","");try{$("g-url").value=SHEET_URL;}catch(e){}lastSheetErr="";toast("Link da planilha atualizado para o Apps Script versão "+b.versao+".");setTimeout(()=>sheetSync(),300);return true;}return false;}
setTimeout(()=>{sheetMelhorLink().then(m=>{if(m&&$("v-ncaud")&&!$("v-ncaud").hidden)paintNCA();});},4000);
const sheetIdCurto=u=>{const m=String(u||"").match(/\/s\/([^/]+)\/exec/);return m?"…"+m[1].slice(-6):u;};
async function ncaVersao(){const el=$("nca-ver");if(!el||!SHEET_URL)return;if(await sheetMelhorLink()){paintNCA();return;}try{const j=await sheetVer(SHEET_URL);if(!j)throw new Error("sem resposta");const v=+j.versao||0;
  el.innerHTML=v>=GS_MIN?'Apps Script conectado: versão '+v+(j.planilha?' · planilha “'+esc(j.planilha)+'”':'')+'. Toque em Enviar agora.':'<b style="color:#B91C1C">O link que o app usa ainda roda o Apps Script versão '+(v||"antiga")+(j.planilha?' (planilha “'+esc(j.planilha)+'”)':'')+'. Precisa ser '+GS_MIN+'.</b> O código do editor já está certo; falta a <b>implantação</b> que o app usa (ID terminado em <b>'+esc(sheetIdCurto(SHEET_URL))+'</b>) apontar para ele: Implantar → Gerenciar implantações → escolha na lista a implantação com esse ID → lápis → Versão: <b>Nova versão</b> → Implantar.'+(SHEET_URL!==SHEET_DEFAULT?' <a href="#" id="nca-pad">Usar o link padrão do app</a>':'');const pd=$("nca-pad");if(pd)pd.onclick=e=>{e.preventDefault();SHEET_URL=SHEET_DEFAULT;store.set("audcd_sheet_url","");toast("Link padrão restaurado.");paintNCA();};}
  catch(e){el.textContent="Não consegui ler o link do Apps Script ("+(e.message||e)+"). Confira a aba Bases.";}}
function ncaAlertas(){let n=0;try{if(gPerm("ce_gest")){const S=ncaResumo();n=S.pend.length+S.adv.length;}}catch(e){}const b=$("nav-nca");if(b){b.hidden=!n;b.textContent=n;}return n;}
async function ncaStatus(r,st){const now=new Date(),upd={Status:st,Aplicada_Em:st==="Aplicada"?fmtDT(now):"",Aplicada_Por:nomeAud()};const id=String(r.ID_Auditoria);
  const q=queue.find(x=>x.rec&&String(x.rec.ID_Auditoria)===id);
  if(q){Object.assign(q.rec,upd);saveQueue();}
  const h=HIST.get(id),local=h&&h._sheet!==SHEET_URL;let pend=false;
  if(local){Object.assign(h,upd);await histPut(h);sheetSync();}
  else if(!DEMO&&SHEET_URL){try{if(!navigator.onLine)throw new Error("sem internet");const j=await ppPost({acao:"ncaud_status",id,status:upd.Status,aplicadaEm:upd.Aplicada_Em,aplicadaPor:upd.Aplicada_Por});if(!j||!j.ok)throw new Error((j&&j.erro)||"sem resposta");}
    catch(e){pend=true;toast("Salvo no aparelho. A situação vai para a planilha assim que ela responder ("+e.message+").");}}
  if(h&&!local){Object.assign(h,upd);histPut(h);}NCST[id]=Object.assign({},upd,pend?{_pend:1}:{});try{store.set("audcd_ncst",NCST);}catch(e){}
  try{const b=FECH.dados&&FECH.dados.ncaud;if(b&&b.colunas){const ci=b.colunas.indexOf("ID_Auditoria");b.registros.forEach(x=>{if(String(x[ci])===id)Object.entries(upd).forEach(([k,v])=>{const i=b.colunas.indexOf(k);if(i>=0)x[i]=v;});});}}catch(e){}
  Object.assign(r,upd);ncaAlertas();return true;}
function ncaAdvDoc(c,rec){const row=(k,v)=>'<tr><td class="k">'+k+'</td><td>'+(v===""||v==null?"–":esc(v))+'</td></tr>';
  return '<div class="pd"><div class="pd-h"><img src="'+LOGO_BLUE+'" alt="Santa Therezinha"><div class="r"><h1>Solicitação de advertência</h1><p>Gestão do Controle de Estoque · Nº '+esc(rec.ID_Auditoria)+'</p></div></div>'+
    '<h2>1. Identificação</h2><table>'+row("Data",rec.DataHora)+row("Colaborador",c.nome+(c.mat?" – matrícula "+c.mat:""))+row("Setor","Controle de Estoque — Auditoria")+row("Solicitante",nomeAud())+row("Motivo","Baixa produtividade: reincidência de não conformidade por meta não atingida")+'</table>'+
    '<h2>2. Não conformidades que fundamentam a solicitação</h2><table class="lt"><thead><tr><th>Nº</th><th>Período</th><th>Indicador(es)</th><th>Atingimento</th><th>Situação</th></tr></thead><tbody>'+
      c.novas.map(r=>'<tr><td>'+esc(r.ID_Auditoria)+'</td><td>'+esc(r.Periodo||"")+'</td><td>'+esc(r.Meta||"")+'</td><td class="n">'+esc(r.Percentual||"–")+'</td><td>'+esc(r.Status||"")+(r.Aplicada_Em?'<br><small>aplicada em '+esc(String(r.Aplicada_Em).slice(0,10))+'</small>':'')+'</td></tr>').join("")+'</tbody></table>'+
    '<h2>3. Solicitação</h2><div class="obs">Diante de '+c.novas.length+' não conformidades por não cumprimento das metas de produtividade, já comunicadas ao colaborador com orientação e plano de ação, solicita-se ao Departamento Pessoal / RH a análise e a aplicação de advertência, conforme o regulamento interno.</div>'+
    '<p class="decl">A aplicação da medida disciplinar cabe ao RH, observando a proporcionalidade, a imediatidade e o histórico do colaborador. Este documento registra o histórico de desempenho e não substitui a advertência formal.</p>'+
    '<div class="sg sg2"><div><b>Gestor solicitante</b>'+esc(nomeAud())+'<small>Data: ____/____/______</small></div><div><b>Recebido pelo RH</b>&nbsp;<small>Data: ____/____/______</small></div></div></div>';}
async function ncaSolicitarAdv(c){if(!confirm("Registrar a solicitação de advertência de "+gmTitulo(c.nome)+" ("+c.novas.length+" NCs por baixa produtividade) e imprimir o documento para o RH?"))return;
  const now=new Date(),rec={_aba:"ncaud",ID_Auditoria:newId("ADV"),Data:fdISO(todayISO()),DataHora:fmtDT(now),ts:now.getTime(),Matricula_Auditor:NC_GESTOR.mat,Nome_Auditor:NC_GESTOR.nome,Matricula_Colaborador:c.mat||"",Nome_Colaborador:c.nome,Tipo:NCA_TIPO_ADV,
    Meta:"",Periodo:c.novas.map(r=>r.Periodo).join(" · "),Descricao:"Reincidência por baixa produtividade. NCs: "+c.novas.map(r=>r.ID_Auditoria).join(", "),Medida:"Solicitação de advertência ao RH",Status:"Solicitada",Origem:"Alerta automático",Chave:c.novas.map(r=>r.ID_Auditoria).join(",")};
  await saveRec(rec);openDoc({html:ncaAdvDoc(c,rec),multi:false,name:"Solicitacao_Advertencia_"+(c.mat||"")+".pdf",title:"Solicitação de advertência",short:"Solicitação de advertência – "+c.nome,text:"*SOLICITAÇÃO DE ADVERTÊNCIA*\n"+c.nome});ncaAlertas();paintNCA();}
/* bloco de alertas na tela de NC dos auditores */
function ncaAlertaHTML(){const S=ncaResumo();if(!S.pend.length&&!S.adv.length)return "";
  return (S.adv.length?'<div class="nca-al nca-adv"><div class="nca-ah"><b>Solicitar advertência</b><span>2 não conformidades por baixa produtividade</span></div>'+S.adv.map((c,i)=>'<div class="nca-ai"><div><b>'+esc(String(c.nome||"").toUpperCase())+'</b><small>Matrícula '+esc(c.mat||"–")+' · NCs: '+c.novas.map(r=>esc(r.Periodo||r.ID_Auditoria)).join(" e ")+'</small></div><button type="button" class="save sm" data-nadv="'+i+'">Solicitar advertência</button></div>').join("")+'</div>':'')+
    (S.pend.length?'<div class="nca-al"><div class="nca-ah"><b>Não conformidades para aplicar</b><span>'+S.pend.length+' gerada(s) automaticamente no fechamento da semana · aplicar na segunda-feira</span></div>'+S.pend.map((r,i)=>'<div class="nca-ai"><div><b>'+esc(String(r.Nome_Colaborador||"").toUpperCase())+'</b><small>Matrícula '+esc(r.Matricula_Colaborador||"–")+' · '+esc(r.Periodo||"")+' · '+esc(r.Meta||"")+' · '+esc(r.Percentual||"")+'</small></div><div class="nca-bt"><button type="button" class="save sm" data-napl="'+i+'">Aplicar e imprimir</button><button type="button" class="btn sm" data-ndis="'+i+'">Dispensar</button></div></div>').join("")+'</div>':'');}
function ncaAlertaBind(box){const S=ncaResumo();box.querySelectorAll("[data-nadv]").forEach(b=>b.onclick=()=>ncaSolicitarAdv(S.adv[+b.dataset.nadv]));
  box.querySelectorAll("[data-napl]").forEach(b=>b.onclick=async()=>{const r=S.pend[+b.dataset.napl];b.disabled=true;if(await ncaStatus(r,"Aplicada")){ncaAbrir(r);paintNCA();}else b.disabled=false;});
  box.querySelectorAll("[data-ndis]").forEach(b=>b.onclick=async()=>{const r=S.pend[+b.dataset.ndis];if(!confirm("Dispensar a NC de "+gmTitulo(r.Nome_Colaborador)+"? Ela fica no histórico como dispensada e não conta para advertência."))return;if(await ncaStatus(r,"Dispensada"))paintNCA();});}

// ---------- ociosidade ----------
const OC_ABAS=["ruas","retorno","cargas","procura","saldo","validade","contagem","aero","sac","adega","pp","solicit"];
function ocCalc(P){const c=gmCfg(),lim=(c.ocLimiar||15)*6e4,jor=(c.ocJornada||528)*6e4,D=FECH.dados||{},A={};
  OC_ABAS.forEach(a=>gmRows(D,a).forEach(r=>{if(!r.ts||r.ts<P.de||r.ts>=P.ate)return;const p=gmPessoa(r.Matricula_Auditor,r.Nome_Auditor);if(!p)return;const mat=p.mat;if(gestMats().indexOf(mat)>=0)return;
    const k=mat;const x=A[k]=A[k]||{k,mat,nome:p.nome||"",dias:{}};if(!x.nome&&p.nome)x.nome=p.nome;const dk=fxDiaKey(r.ts);(x.dias[dk]=x.dias[dk]||[]).push({t:r.ts,a});}));
  return Object.values(A).map(x=>{if(!x.nome||/^\d+$/.test(x.nome))x.nome=gmNomeDe(x.mat)||x.nome||x.mat;let tot={dias:0,lanc:0,jan:0,ativo:0,ocio:0,fora:0,alm:0,maior:0,maiorEm:0};const D2=[];
    Object.entries(x.dias).sort().forEach(([dk,L])=>{L.sort((a,b)=>a.t-b.t);const ini=L[0].t,fim=L[L.length-1].t,gaps=[];for(let i=1;i<L.length;i++){const g=L[i].t-L[i-1].t;if(g>lim)gaps.push({de:L[i-1].t,ate:L[i].t,g});}
      let alm=0;const gg=gaps.slice().sort((a,b)=>b.g-a.g)[0];if(gg&&gg.g>=30*6e4&&gg.g<=90*6e4){alm=gg.g;gg.alm=true;}
      const ocio=gaps.filter(g=>!g.alm).reduce((s,g)=>s+g.g,0),jan=fim-ini,ativo=Math.max(0,jan-ocio-alm),fora=Math.max(0,jor-(jan-alm));
      const mg=gaps.filter(g=>!g.alm).sort((a,b)=>b.g-a.g)[0];if(mg&&mg.g>tot.maior){tot.maior=mg.g;tot.maiorEm=mg.de;}
      tot.dias++;tot.lanc+=L.length;tot.jan+=jan;tot.ativo+=ativo;tot.ocio+=ocio;tot.fora+=fora;tot.alm+=alm;D2.push({dk,ini,fim,n:L.length,ativo,ocio,fora,alm,gaps:gaps.filter(g=>!g.alm)});});
    const ociT=tot.ocio+tot.fora,jorT=tot.dias*jor;return Object.assign(x,tot,{pct:jorT?Math.min(1,ociT/jorT):0,ociT,jorT,lista:D2});}).filter(x=>x.dias).sort((a,b)=>b.pct-a.pct);}
const ocH=ms=>{const m=Math.round(ms/6e4);return Math.floor(m/60)+"h"+String(m%60).padStart(2,"0");};
const ocHr=t=>new Date(t).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"});
function ocCor(p){return p>=.4?"#B91C1C":p>=.25?"#C2410C":p>=.15?"#A16207":"#15803D";}
function paintOcio(){const box=$("gm-ocio");if(!box)return;gmPrep(paintOcio);
  if(!FECH.dados){box.innerHTML=gmPerBar()+'<div class="nw-sk">'+'<div></div>'.repeat(4)+'</div>';gmBindBar(paintOcio);return;}
  const P=gmPeriodo(GM.per,GM.off),c=gmCfg(),L=ocCalc(P),tO=L.reduce((s,x)=>s+x.ociT,0),tJ=L.reduce((s,x)=>s+x.jorT,0),med=tJ?tO/tJ:0;
  box.innerHTML=gmPerBar()+
    '<div class="gm-hero"><div><span>Ociosidade média da equipe</span><b>'+Math.round(med*100)+'%</b></div><div><span>Horas ociosas no período</span><b>'+ocH(tO)+'</b></div><div><span>Colaboradores</span><b>'+L.length+'</b></div><div class="gm-leg">Jornada de '+ocH(c.ocJornada*6e4)+' por dia · intervalo ocioso: mais de '+c.ocLimiar+' min sem lançamento<small>Estimativa pelos horários dos lançamentos na planilha</small></div></div>'+
    (L.length?'<div class="fx-c"><h3>Ociosidade por colaborador</h3><div class="oc-bars">'+L.map(x=>'<div class="oc-r"><span>'+esc(gmTitulo(x.nome))+'</span><i><b style="width:'+Math.max(2,Math.round(x.pct*100))+'%;background:'+ocCor(x.pct)+'"></b></i><em style="color:'+ocCor(x.pct)+'">'+Math.round(x.pct*100)+'%</em></div>').join("")+'</div></div>'+
      '<div class="fx-c" style="margin-top:14px"><h3>Detalhe</h3><div class="tw"><table class="gm-t"><thead><tr><th>Colaborador</th><th>Dias</th><th>Lançamentos</th><th>1º ao último lançamento</th><th>Tempo ativo</th><th>Intervalos ociosos</th><th>Jornada sem lançamento</th><th>Ociosidade</th><th>Maior intervalo</th><th></th></tr></thead><tbody>'+
      L.map((x,i)=>'<tr><td><b>'+esc(String(x.nome).toUpperCase())+'</b><small>Matrícula '+esc(x.mat||"–")+'</small></td><td>'+x.dias+'</td><td>'+x.lanc.toLocaleString("pt-BR")+'</td><td>'+ocH(x.jan)+'<small>média '+ocH(x.jan/x.dias)+'/dia</small></td><td>'+ocH(x.ativo)+'</td><td>'+ocH(x.ocio)+'</td><td>'+ocH(x.fora)+'</td><td><b style="color:'+ocCor(x.pct)+'">'+Math.round(x.pct*100)+'%</b><small>'+ocH(x.ociT)+' de '+ocH(x.jorT)+'</small></td><td>'+(x.maior?ocH(x.maior)+'<small>'+new Date(x.maiorEm).toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"})+' às '+ocHr(x.maiorEm)+'</small>':'–')+'</td><td><button type="button" class="btn sm" data-ocd="'+i+'">Dias</button></td></tr>'+
        '<tr class="oc-det" id="ocd-'+i+'" hidden><td colspan="10">'+x.lista.map(d=>'<div class="oc-dia"><b>'+new Date(d.ini).toLocaleDateString("pt-BR",{weekday:"short",day:"2-digit",month:"2-digit"})+'</b> '+ocHr(d.ini)+'–'+ocHr(d.fim)+' · '+d.n+' lançamentos · ativo '+ocH(d.ativo)+(d.alm?' · almoço '+ocH(d.alm):'')+' · ocioso '+ocH(d.ocio)+(d.gaps.length?'<small>Intervalos: '+d.gaps.map(g=>ocHr(g.de)+'–'+ocHr(g.ate)+' ('+ocH(g.g)+')').join(", ")+'</small>':'')+'</div>').join("")+'</td></tr>').join("")+'</tbody></table></div>'+
      '<p class="note">Como é calculado: em cada dia trabalhado, os intervalos de mais de '+c.ocLimiar+' minutos sem nenhum lançamento contam como ociosos (o maior intervalo entre 30 e 90 minutos é considerado almoço). "Jornada sem lançamento" é a parte da jornada de '+ocH(c.ocJornada*6e4)+' fora do período entre o primeiro e o último lançamento. É uma estimativa: tarefas sem lançamento no app (reuniões, apoio a outros setores) aparecem como ociosidade. Ajuste a jornada e o limite em Painel de metas → Configurar metas.</p></div>':'<p class="fx-e">Nenhum lançamento de auditor no período.</p>');
  gmBindBar(paintOcio);box.querySelectorAll("[data-ocd]").forEach(b=>b.onclick=()=>{const t=$("ocd-"+b.dataset.ocd);t.hidden=!t.hidden;});}
BAND.ocio=["Ociosidade","Tempo ativo e ocioso de cada colaborador, pelos horários dos lançamentos."];
(function(){const s=document.createElement("style");s.textContent=`
.nca-al{border:1px solid #FCD34D;background:#FFFBEB;border-radius:14px;padding:12px 14px;margin-bottom:12px}.nca-adv{border-color:#FCA5A5;background:#FEF2F2}
html.dark .nca-al{background:#2A2312;border-color:#A16207}html.dark .nca-adv{background:#2A1414;border-color:#B91C1C}
.nca-ah{display:flex;flex-wrap:wrap;gap:8px;align-items:baseline;margin-bottom:6px}.nca-ah b{font-size:1rem}.nca-ah span{color:var(--muted);font-size:.85rem}
.nca-ai{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}.nca-ai small{display:block;color:var(--muted)}.nca-bt{display:flex;gap:6px;flex-wrap:wrap}.nca-ai .save{margin:0;width:auto;min-height:36px;padding:0 14px}
.oc-bars{display:grid;gap:6px}.oc-r{display:grid;grid-template-columns:minmax(120px,220px) 1fr 50px;gap:10px;align-items:center;font-size:.9rem}.oc-r i{height:14px;background:var(--line);border-radius:7px;overflow:hidden;display:block}.oc-r i b{display:block;height:100%;border-radius:7px}.oc-r em{font-style:normal;font-weight:800;text-align:right}
.oc-dia{padding:6px 0;border-bottom:1px dashed var(--line);font-size:.85rem}.oc-dia small{display:block;color:var(--muted)}
html.mob .nca-ai{flex-direction:column;align-items:stretch}.hm-card.nca-al{background:#FFFBEB;border-color:#FCD34D}.hm-card.nca-adv{background:#FEF2F2;border-color:#FCA5A5}html.dark .hm-card.nca-al{background:#2A2312}html.dark .hm-card.nca-adv{background:#2A1414}`;document.head.appendChild(s);})();

// ===================== NC dos auditores: textos prontos por situação e medida =====================
const NCA_TIPOS=["Meta não atingida","Erro identificado pelo gestor","Erro de lançamento na auditoria","Prazo não cumprido","Descumprimento de procedimento","Ociosidade acima do esperado"];
const NCA_MEDIDAS=["Orientação e plano de ação","Advertência verbal","Advertência escrita","Solicitação de advertência ao RH"];
const NCA_FATO={
  "Meta não atingida":"No período {periodo}, o(a) colaborador(a) {colab} não atingiu a meta estabelecida para o indicador {meta}, conforme os resultados registrados no sistema de auditoria e as metas previamente comunicadas à equipe.",
  "Erro identificado pelo gestor":"Em {data}, a gestão identificou falha na execução das atividades do(a) colaborador(a) {colab}: [descreva o fato, o local (rua/endereço/carga) e o impacto para o estoque].",
  "Erro de lançamento na auditoria":"Em {data}, foi identificado lançamento incorreto na auditoria realizada pelo(a) colaborador(a) {colab} — registro divergente da conferência física [informe o item, o endereço e a divergência], comprometendo a confiabilidade das informações de estoque.",
  "Prazo não cumprido":"O(A) colaborador(a) {colab} não concluiu dentro do prazo estabelecido a atividade sob sua responsabilidade [descreva a atividade e o prazo], sem justificativa prévia à gestão.",
  "Descumprimento de procedimento":"Em {data}, o(a) colaborador(a) {colab} deixou de seguir o procedimento operacional [descreva o procedimento], no qual foi previamente treinado(a) e que foi comunicado ao setor.",
  "Ociosidade acima do esperado":"No período {periodo}, foi verificado tempo sem registro de atividades acima do esperado para a jornada do(a) colaborador(a) {colab}, conforme os horários dos lançamentos no sistema de auditoria."};
const NCA_MED={
  "Orientação e plano de ação":"O(A) colaborador(a) foi orientado(a) sobre o padrão esperado e sobre a importância do indicador para o resultado do Controle de Estoque. Fica estabelecido plano de ação, com acompanhamento até o prazo definido neste documento. Esta orientação tem caráter educativo e não constitui penalidade.",
  "Advertência verbal":"Diante do ocorrido, o(a) colaborador(a) recebe advertência verbal, registrada neste documento para fins de histórico. Foi orientado(a) a corrigir a conduta, ciente de que a reincidência poderá resultar em advertência escrita, conforme o regulamento interno.",
  "Advertência escrita":"Pelo presente, o(a) colaborador(a) é advertido(a) por escrito em razão do fato descrito, nos termos do regulamento interno e do poder disciplinar do empregador. A reincidência poderá ensejar medidas disciplinares mais severas, observada a legislação trabalhista.",
  "Solicitação de advertência ao RH":"Considerando a reincidência registrada, a gestão encaminha o caso ao Departamento Pessoal / RH para análise e eventual aplicação de medida disciplinar, conforme o regulamento interno."};
function ncaTexto(tipo,colab,extra){extra=extra||{};return String(NCA_FATO[tipo]||"").replace(/\{colab\}/g,gmTitulo(colab||"")||"[colaborador]").replace(/\{periodo\}/g,extra.periodo||"[período]").replace(/\{meta\}/g,extra.meta||"[indicador]").replace(/\{data\}/g,extra.data||new Date().toLocaleDateString("pt-BR"));}

// ===================== Desempenho dos auditores (painel de gestão) =====================
BAND.desemp=["Desempenho dos auditores","Produção, qualidade, metas, ociosidade e histórico de cada auditor."];
function dsRowsDe(x,P){const D=FECH.dados||{},out=[];const nk=gmNk(x.nome);
  OC_ABAS.forEach(a=>fxRows(D[a]).forEach(r=>{if(!r.ts||r.ts<P.de||r.ts>=P.ate)return;const m=String(r.Matricula_Auditor||"").trim();if((x.mat&&m===x.mat)||(!m&&gmNk(r.Nome_Auditor)===nk)||(m&&!x.mat&&gmNk(r.Nome_Auditor)===nk))out.push(Object.assign({_a:a},r));}));return out;}
const DS_NOME={ruas:"Ruas",retorno:"Retorno",cargas:"Cargas",procura:"Procura",saldo:"Saldo de picking",validade:"Validade",contagem:"Contagem/Aéreo",aero:"Aéreo (NC)",sac:"SAC",adega:"ADEGA",pp:"Prevenção",solicit:"Solicitações"};
function dsResumo(P){const R=gmCalc(P),O={};try{ocCalc(P).forEach(o=>{O[o.mat||gmNk(o.nome)]=o;});}catch(e){}const NC=ncaTodas(),FB=fxRows(FECH.dados&&FECH.dados.feedback);
  return R.L.map(x=>{const rs=dsRowsDe(x,P),it=gmFbDados(R,x),g=it.filter(i=>i.ref!=null),meta=g.length?g.reduce((s,i)=>s+Math.min(1.2,i.ref),0)/g.length:null,o=O[x.mat]||O[gmNk(x.nome)];
    const meus=NC.filter(r=>(x.mat&&String(r.Matricula_Colaborador)===x.mat)||gmNk(r.Nome_Colaborador)===gmNk(x.nome)),fb=FB.filter(r=>(x.mat&&String(r.Matricula_Colaborador)===x.mat)||gmNk(r.Nome_Colaborador)===gmNk(x.nome));
    const dias=new Set(rs.map(r=>fxDiaKey(r.ts))).size,achados=rs.filter(r=>pbool(r.Possui_NC)||(r._a==="saldo"&&r.Situacao&&r.Situacao!=="OK")).length;
    return {x,rs,it,meta,oc:o?o.pct:null,ocH:o?o.ociT:0,dias,lanc:rs.length,media:dias?rs.length/dias:0,achados,nc:meus.filter(r=>r.Tipo!==NCA_TIPO_ADV),adv:meus.filter(r=>r.Tipo===NCA_TIPO_ADV),fb};}).sort((a,b)=>(b.meta==null?-1:b.meta)-(a.meta==null?-1:a.meta)||b.lanc-a.lanc);}
function paintDesemp(){const box=$("gm-desemp");if(!box)return;gmPrep(paintDesemp);
  if(!FECH.dados){box.innerHTML=gmPerBar()+'<div class="nw-sk">'+'<div></div>'.repeat(4)+'</div>';gmBindBar(paintDesemp);return;}
  const P=gmPeriodo(GM.per,GM.off),L=dsResumo(P),sel=GM.dsel&&L.find(d=>d.x.k===GM.dsel);
  const pct=v=>v==null?'–':Math.round(v*100)+'%',corM=v=>gmSit(v,P.ate>Date.now()).c;
  let html=gmPerBar()+'<div class="ds-sel"><label>Auditor <select class="in" id="ds-a"><option value="">Todos os auditores</option>'+L.map(d=>'<option value="'+esc(d.x.k)+'"'+(sel&&sel.x.k===d.x.k?" selected":"")+'>'+esc(gmTitulo(d.x.nome))+'</option>').join("")+'</select></label></div>';
  if(!sel){html+=L.length?'<div class="fx-c"><h3>Ranking do período</h3><div class="tw"><table class="gm-t ds-t"><thead><tr><th>#</th><th>Auditor</th><th>Lançamentos</th><th>Dias</th><th>Média/dia</th><th>NCs encontradas</th><th>Metas</th><th>Ociosidade</th><th>NCs recebidas</th><th>Advertências</th></tr></thead><tbody>'+
      L.map((d,i)=>'<tr data-ds="'+esc(d.x.k)+'"><td><span class="hm-eqn">'+(i+1)+'</span></td><td><b>'+esc(String(d.x.nome).toUpperCase())+'</b><small>Matrícula '+esc(d.x.mat||"–")+'</small></td><td>'+d.lanc.toLocaleString("pt-BR")+'</td><td>'+d.dias+'</td><td>'+d.media.toFixed(1).replace(".",",")+'</td><td>'+d.achados+'</td><td><b style="color:'+corM(d.meta)+'">'+pct(d.meta)+'</b></td><td><b style="color:'+(d.oc==null?"#64748B":ocCor(d.oc))+'">'+pct(d.oc)+'</b></td><td>'+d.nc.length+'</td><td>'+(d.adv.length?'<b style="color:#B91C1C">'+d.adv.length+'</b>':'0')+'</td></tr>').join("")+'</tbody></table></div></div>'+
      '<div class="fx-row" style="grid-template-columns:1fr 1fr;margin-top:14px">'+fxCard("Lançamentos por auditor",fxCols(L.slice().sort((a,b)=>b.lanc-a.lanc).slice(0,12).map(d=>({l:gmTitulo(d.x.nome).split(" ")[0],t:gmTitulo(d.x.nome)+": "+d.lanc,v:d.lanc,txt:String(d.lanc),c:"#103F79"}))))+
        fxCard("Atingimento das metas por auditor",fxCols(L.filter(d=>d.meta!=null).map(d=>({l:gmTitulo(d.x.nome).split(" ")[0],t:gmTitulo(d.x.nome)+": "+pct(d.meta),v:Math.round(d.meta*100),txt:pct(d.meta),c:corM(d.meta)}))))+'</div>':'<p class="fx-e">Nenhum auditor com lançamentos no período.</p>';}
  else{const d=sel,porD={},porA={};d.rs.forEach(r=>{const k=fxDiaKey(r.ts);(porD[k]=porD[k]||{ts:r.ts,n:0}).n++;porA[r._a]=(porA[r._a]||0)+1;});
    const sem=[5,4,3,2,1,0].map(i=>{const PP=gmPeriodo("semana",GM.per==="semana"?GM.off-i:-i);let v=null;try{const RR=gmCalc(PP),xx=RR.L.find(y=>(d.x.mat&&y.mat===d.x.mat)||gmNk(y.nome)===gmNk(d.x.nome));if(xx){const g=gmFbDados(RR,xx).filter(t=>t.ref!=null);v=g.length?g.reduce((s,t)=>s+Math.min(1.2,t.ref),0)/g.length:null;}}catch(e){}return {l:new Date(PP.de).toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"}),v};});
    html+='<div class="ds-head"><div><b>'+esc(String(d.x.nome).toUpperCase())+'</b><span>Matrícula '+esc(d.x.mat||"–")+' · '+esc(P.lab)+'</span></div><button type="button" class="btn sm" id="ds-fb">Imprimir feedback</button></div>'+
      fxKpis([{t:"Lançamentos",v:d.lanc.toLocaleString("pt-BR"),c:"#103F79",s:d.dias+" dia(s) · "+d.media.toFixed(1).replace(".",",")+"/dia"},{t:"NCs encontradas",v:d.achados,c:"#B45309",s:"nas auditorias do período"},{t:"Metas",v:pct(d.meta),c:corM(d.meta),s:gmSit(d.meta,P.ate>Date.now()).t},
        {t:"Ociosidade",v:pct(d.oc),c:d.oc==null?"#64748B":ocCor(d.oc),s:d.ocH?ocH(d.ocH)+" sem lançamento":""},{t:"NCs recebidas",v:d.nc.length,c:"#DC2626",s:d.nc.filter(r=>r.Status==="Aplicada").length+" aplicada(s)"},{t:"Advertências",v:d.adv.length,c:d.adv.length?"#B91C1C":"#16A34A",s:d.fb.length+" feedback(s) emitido(s)"}])+
      '<div class="fx-row" style="grid-template-columns:1.4fr 1fr">'+fxCard("Lançamentos por dia",fxCols(Object.keys(porD).sort().map(k=>({l:fxDia(porD[k].ts),v:porD[k].n,txt:String(porD[k].n),c:"#103F79"}))))+
        fxCard("Por tipo de auditoria",fxBars(Object.entries(porA).sort((a,b)=>b[1]-a[1]).map(([a,n])=>({l:DS_NOME[a]||a,v:n,txt:String(n),c:"#2563EB"}))))+'</div>'+
      '<div class="fx-row" style="grid-template-columns:1fr 1fr;margin-top:10px">'+fxCard("Metas no período",d.it.length?fxBars(d.it.map(i=>({l:i.m.t,v:Math.round((i.pct||0)*100),txt:i.pct==null?(i.txt||"–"):Math.round(i.pct*100)+"% · "+i.si.t+(i.k==="vld"&&i.txt?" · "+i.txt:""),c:i.si.c}))):'<p class="fx-e">Sem metas no período.</p>')+
        fxCard("Evolução das metas (últimas 6 semanas)",fxCols(sem.map(w=>({l:w.l,v:w.v==null?0:Math.round(w.v*100),txt:w.v==null?"–":Math.round(w.v*100)+"%",c:w.v==null?"#CBD5E1":corM(w.v)}))))+'</div>'+
      '<div class="fx-row" style="grid-template-columns:1fr 1fr;margin-top:10px">'+fxCard("Histórico de não conformidades",d.nc.length+d.adv.length?fxTable([{t:"Data"},{t:"Tipo"},{t:"Medida"},{t:"Situação"}],d.nc.concat(d.adv).sort((a,b)=>(b.ts||0)-(a.ts||0)).slice(0,12).map(r=>[esc(String(r.DataHora||"").slice(0,10)),esc(r.Tipo||""),esc(r.Medida||""),esc(r.Status||"")])):'<p class="fx-e">Nenhuma não conformidade registrada.</p>')+
        fxCard("Feedbacks emitidos",d.fb.length?fxTable([{t:"Data"},{t:"Período"},{t:"Resumo"}],d.fb.sort((a,b)=>(b.ts||0)-(a.ts||0)).slice(0,10).map(r=>[esc(String(r.DataHora||"").slice(0,10)),esc(r.Periodo||""),esc(String(r.Resumo||"").slice(0,90))])):'<p class="fx-e">Nenhum feedback emitido.</p>')+'</div>';}
  box.innerHTML=html;gmBindBar(paintDesemp);$("ds-a").onchange=e=>{GM.dsel=e.target.value||null;paintDesemp();};
  box.querySelectorAll("[data-ds]").forEach(t=>t.onclick=()=>{GM.dsel=t.dataset.ds;paintDesemp();box.scrollIntoView({block:"start"});});
  const fb=$("ds-fb");if(fb&&sel)fb.onclick=()=>gmFbAbrir(gmCalc(P),[sel.x]);}
