      fxLista().map(k=>'<button type="button" data-fxk="'+k+'"'+(k===FECH.tipo?' class="on"':'')+'><span class="hm-ic"><svg viewBox="0 0 24 24" aria-hidden="true">'+(APP_ICO[FXM_ICO[k]]||"")+'</svg></span>'+esc(FX_TAB[k]||k)+'</button>').join("")+'</div></div>';
